def read_dev_items_1(items, limit=10):
    """Return normalized labels from the first nonempty items."""
    labels = []
    for item in items:
        label = item.strip().lower()
        if not label:
            continue
        labels.append(label)
        if len(labels) >= limit:
            break
    return labels

